// Workflow 00 – Groq Connection Test (owner: Tharindu)
// Node: "Build test request". Prepares a tiny chat completion that must answer
// with a fixed JSON object, so the response can be validated end to end.
// ---- shared: common helpers ----
const SECRET_PATTERNS = [
  /(authorization|api[_-]?key|token|secret|password|signature)(["'\s:=]+)([^\s"',}]+)/gi,
  /\bgsk_[A-Za-z0-9]{10,}\b/g,          // Groq keys
  /\bgh[pousr]_[A-Za-z0-9]{20,}\b/g,     // GitHub tokens
  /\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{5,}\b/g, // JWTs
  /https:\/\/hooks\.slack\.com\/[^\s"']+/g,
  /https:\/\/discord(?:app)?\.com\/api\/webhooks\/[^\s"']+/g,
];

function redact(text) {
  let out = String(text == null ? '' : text);
  for (const re of SECRET_PATTERNS) {
    // Only the first pattern has capture groups (key + separator are kept).
    out = out.replace(re, (m, a, b) => (typeof a === 'string' && typeof b === 'string' ? a + b + '[REDACTED]' : '[REDACTED]'));
  }
  return out;
}

function truncate(text, max) {
  const s = String(text == null ? '' : text);
  return s.length > max ? s.slice(0, max - 1) + '…' : s;
}

function envInt(env, name, fallback, min, max) {
  const raw = env[name];
  const n = raw === undefined || raw === '' ? fallback : Number(raw);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, Math.round(n)));
}

function envNumber(env, name, fallback) {
  const n = Number(env[name]);
  return env[name] === undefined || env[name] === '' || !Number.isFinite(n) ? fallback : n;
}

// Classify the output of an HTTP Request node that runs with
// "full response" + "never error" + onError=continueRegularOutput.
// kind: ok | timeout | unavailable | auth | rate_limited | not_found | not_implemented | invalid | server_error | client_error
function classifyHttp(item, opts) {
  const o = opts || {};
  if (item && item.error) {
    const msg = String(item.error.message || item.error.description || item.error || '');
    const code = String(item.error.code || '');
    if (/timeout|ETIMEDOUT|ESOCKETTIMEDOUT|ECONNABORTED/i.test(msg + code)) {
      return { kind: 'timeout', retryable: true, status: null, message: 'Request timed out.' };
    }
    return { kind: 'unavailable', retryable: true, status: null, message: redact(truncate(msg || 'Connection failed.', 300)) };
  }
  const status = Number(item && item.statusCode);
  if (!status) return { kind: 'invalid', retryable: false, status: null, message: 'No HTTP status in response.' };
  if (status >= 200 && status < 300) return { kind: 'ok', retryable: false, status, message: null };
  const bodyMsg = item.body && typeof item.body === 'object' ? (item.body.message || (item.body.error && (item.body.error.message || item.body.error))) : item.body;
  const message = redact(truncate(bodyMsg || ('HTTP ' + status), 300));
  if (status === 401 || status === 403) return { kind: 'auth', retryable: false, status, message };
  if (status === 429) return { kind: 'rate_limited', retryable: true, status, message };
  if (status === 404 && o.notFoundMeansNotImplemented) return { kind: 'not_implemented', retryable: false, status, message: 'Backend endpoint is not implemented yet (404).' };
  if (status === 404) return { kind: 'not_found', retryable: false, status, message };
  if (status === 503 && o.serviceUnavailableMeansNotConfigured) return { kind: 'not_configured', retryable: true, status, message };
  if (status >= 500) return { kind: 'server_error', retryable: true, status, message };
  return { kind: 'client_error', retryable: false, status, message };
}

// Standard investigation result (automation/schemas/investigation-output.schema.json).
function investigationResult(source, ctx, fields) {
  const f = fields || {};
  return {
    incident_id: ctx.incident_id || null,
    source,
    status: f.status,                 // evidence_found | no_evidence | unavailable | not_configured | invalid_input
    ok: f.status === 'evidence_found' || f.status === 'no_evidence',
    summary: f.summary || '',
    findings: f.findings || [],
    evidence: f.evidence || [],
    confidence: typeof f.confidence === 'number' ? Math.max(0, Math.min(1, f.confidence)) : 0,
    window: f.window || null,
    error: f.error || null,
    collected_at: new Date().toISOString(),
  };
}

// URLSearchParams is not available in the n8n task-runner sandbox (n8n 2.x).
function toQuery(params) {
  return Object.entries(params)
    .filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v)))
    .join('&');
}

function isUuid(v) {
  return typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);
}

// Investigation input (from workflow 01 / 05). Returns { ok, ctx, error }.
function readInvestigationInput(json) {
  const j = json || {};
  const started = j.started_at ? new Date(j.started_at) : null;
  const errors = [];
  if (!j.service_name || typeof j.service_name !== 'string' || !/^[A-Za-z0-9_.:-]{1,100}$/.test(j.service_name)) {
    errors.push('service_name is required (letters, digits, _ . : - only).');
  }
  if (!started || isNaN(started.getTime())) errors.push('started_at must be an ISO timestamp.');
  if (j.incident_id != null && !isUuid(j.incident_id)) errors.push('incident_id must be a UUID or null.');
  return {
    ok: errors.length === 0,
    error: errors.join(' ') || null,
    ctx: {
      incident_id: j.incident_id || null,
      service_name: j.service_name,
      alert_name: j.alert_name || null,
      severity: j.severity || null,
      started_at: started && !isNaN(started.getTime()) ? started.toISOString() : null,
    },
  };
}
// ---- end shared: common ----
// ---- shared: AI (Groq) helpers ----
// Allowed values come from the database CHECK constraints
// (ai_analyses_action_allowed, ai_analyses_severity_allowed, playbooks_action_type_allowed).
const AI_ACTIONS = ['restart', 'rollback', 'scale', 'circuit_breaker'];
const AI_SEVERITIES = ['low', 'medium', 'high', 'critical'];

function groqBaseUrl(env) {
  return String(env.GROQ_API_BASE_URL || 'https://api.groq.com/openai/v1').replace(/\/+$/, '');
}

function groqModel(env) {
  const m = env.GROQ_MODEL;
  if (!m || !/^[A-Za-z0-9._:/-]{1,100}$/.test(m)) throw new Error('GROQ_MODEL is not configured.');
  return m;
}

function groqRequest(env, system, user, maxTokens) {
  return {
    model: groqModel(env),
    temperature: 0.1,
    max_tokens: maxTokens || 1200,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: user },
    ],
  };
}

// Extract the JSON object the model returned. Returns { ok, value, error }.
function parseModelJson(httpItem) {
  const body = httpItem && httpItem.body;
  const content = body && body.choices && body.choices[0] && body.choices[0].message && body.choices[0].message.content;
  if (typeof content !== 'string' || !content.trim()) return { ok: false, error: 'Model response has no content.' };
  let text = content.trim();
  const fence = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/);
  if (fence) text = fence[1];
  try {
    const value = JSON.parse(text);
    if (!value || typeof value !== 'object' || Array.isArray(value)) return { ok: false, error: 'Model response is not a JSON object.' };
    return { ok: true, value, model: body.model || null, usage: body.usage || null };
  } catch (e) {
    return { ok: false, error: 'Model response is not valid JSON.' };
  }
}

function asStringArray(v, maxItems, maxLen) {
  if (!Array.isArray(v)) return null;
  return v.filter((x) => typeof x === 'string' && x.trim()).slice(0, maxItems).map((x) => x.trim().slice(0, maxLen));
}

// Validate an RCA object (automation/schemas/rca-output.schema.json).
// Never trusts the model: unknown actions are rejected, text is length-limited,
// and the result is always marked for human review.
function validateRca(o) {
  const errors = [];
  const out = {};
  if (typeof o.summary !== 'string' || !o.summary.trim()) errors.push('summary is required');
  else out.summary = o.summary.trim().slice(0, 2000);
  if (typeof o.root_cause !== 'string' || !o.root_cause.trim()) errors.push('root_cause is required');
  else out.root_cause = o.root_cause.trim().slice(0, 2000);
  if (!AI_SEVERITIES.includes(o.severity)) errors.push('severity must be one of ' + AI_SEVERITIES.join(', '));
  else out.severity = o.severity;
  if (typeof o.confidence !== 'number' || !(o.confidence >= 0 && o.confidence <= 1)) errors.push('confidence must be a number 0..1');
  else out.confidence = Math.round(o.confidence * 100) / 100;
  for (const key of ['evidence', 'confirmed_findings', 'possible_causes']) {
    const arr = asStringArray(o[key], 20, 500);
    if (arr === null) errors.push(key + ' must be an array of strings');
    else out[key] = arr;
  }
  if (o.recommended_action === null || o.recommended_action === undefined || o.recommended_action === 'none') {
    out.recommended_action = null;
  } else if (AI_ACTIONS.includes(o.recommended_action)) {
    out.recommended_action = o.recommended_action;
  } else {
    errors.push('recommended_action must be one of ' + AI_ACTIONS.join(', ') + ' or null');
  }
  const recs = asStringArray(o.recommendations || [], 10, 500);
  out.recommendations = recs || [];
  out.requires_human_review = true;
  return { ok: errors.length === 0, value: errors.length ? null : out, errors };
}

// Validate a postmortem object (automation/schemas/postmortem-output.schema.json).
function validatePostmortem(o) {
  const errors = [];
  const out = {};
  for (const key of ['title', 'summary', 'root_cause', 'impact', 'remediation', 'recovery_result']) {
    if (typeof o[key] !== 'string' || !o[key].trim()) errors.push(key + ' is required');
    else out[key] = o[key].trim().slice(0, 4000);
  }
  for (const key of ['evidence', 'lessons_learned', 'preventive_actions']) {
    const arr = asStringArray(o[key], 20, 500);
    if (arr === null) errors.push(key + ' must be an array of strings');
    else out[key] = arr;
  }
  if (!Array.isArray(o.timeline)) errors.push('timeline must be an array');
  else {
    out.timeline = o.timeline
      .filter((t) => t && typeof t.time === 'string' && typeof t.event === 'string')
      .slice(0, 50)
      .map((t) => ({ time: t.time.slice(0, 40), event: t.event.slice(0, 500) }));
  }
  return { ok: errors.length === 0, value: errors.length ? null : out, errors };
}
